// ═══════════════════════════════════════════════════════════
// 血月裁判 · 单入口脚本（脚本=裁判 / AI=演员 / 玩家=自由行动）
// 职责：指派 / 夜结算 / 下毒 / 投票处决 / 胜负 / 重开
// 信息隔离铁律（机制总纲 §十二 v2）：
//   - 身份真相只在 $ 层与脚本变量，永不进 AI 可见字段（_ 前缀会注入 prompt）
//   - 玩家血梦/同伴/藏处/被种 → 脚本变量（UI 读，AI 永不可见）
//   - _人物.X.已知 只存【公开传递】的信息；照镜私知存脚本变量
//   - 行为池投放中立可见行为，AI 只见行为事实不知身份因果
// 数值为 §十占位，调参见机制总纲。
// ═══════════════════════════════════════════════════════════

const 名单11 = ['庄晚棠', '白蘅', '灶婶', '小满', '姜芸', '苏黎', '陆霜霜', '闻人夏', '程郁', '顾青芜', '顾青黛'];
const 四神职 = ['铜镜', '药囊', '银匕', '草汁'];
const 物名 = { 铜镜: '狼感铜镜', 药囊: '药炉药囊', 银匕: '祖传银匕', 草汁: '狼毒草汁' };

// ── 数值占位（§十调参表）──
const 参 = {
  搏命同归: 0.40, 搏命击退: 0.25,
  反扑: 0.50,
  做死: 0.70,                 // 狼队做死/留种倾向
  兽袭: 0.60,                 // 夜行兽每夜袭击概率
  NPC银匕随身: 0.80,
  NPC草汁自守: 0.70,
  NPC麻沸散自守: 0.50,
  NPC代众: 0.50,              // NPC 行刑方持银匕以银代众
  NPC自刎: 0.50,              // NPC 被处决时持银匕自刎
  NPC下毒: 0.30,              // NPC 药囊持有者每日下毒概率（一次性）
  神信息暴露: 40,             // 公开传递神信息 → 狼队权重加成
  行为可疑: 15,               // 听了神信息 → 接收者对传递者互疑增量
  同屋好感门槛: 60,           // 同屋请求被接受的最低好感
};

// ── 行为池（§八：中立措辞——只写可见行为，不含身份因果）──
// 狼/民 = 每晨日常行为线索；异样 = 被种者渐进兽化的可见破绽
const 行为池 = {
  庄晚棠: {
    狼: ['庄晚棠在柜台后拨算盘，拨错两次。', '庄晚棠把每间离屋的门牌擦了一遍，动作很慢。'],
    民: ['庄晚棠清点着酒窖存粮，一笔一笔记得很细。', '庄晚棠给每个人的房间添了炭，谁那儿都没落下。'],
    异样: ['庄晚棠午后靠在柜台后打了半个时辰的盹，醒来时眼神涣散。', '庄晚棠的手背添了几道抓痕，她自己说不记得。'],
  },
  白蘅: {
    狼: ['白蘅擦拭廊灯，有一盏她擦了三遍。', '白蘅替众人备好热茶，自己那杯一口没动。'],
    民: ['白蘅检查了每一道门闩，逐一试过。', '白蘅在账房抄写客人名单，字迹一丝不苟。'],
    异样: ['白蘅的梳妆比往日潦草，鬓发乱了半边也没察觉。', '白蘅对着茶杯出神，茶凉透了也没喝一口。'],
  },
  灶婶: {
    狼: ['灶婶炖了一锅肉汤，香气盖过了雪味。', '灶婶念叨着山神，往门槛上抹了灰。'],
    民: ['灶婶把剩粮装进陶罐，封了三层油纸。', '灶婶拉着小满念叨老规矩，声音越来越低。'],
    异样: ['灶婶尝汤时咸淡没尝出来，被小满提醒了才回神。', '灶婶的膝盖撞在桌角，淤青半天就消了，快得反常。'],
  },
  小满: {
    狼: ['小满收拾餐具时打碎了一只碗，愣了很久。', '小满逢人就笑，笑得比平时更甜。'],
    民: ['小满缩在灶边不敢出声，手指绞着围裙。', '小满问灶婶血月要持续几天，问了两遍。'],
    异样: ['小满午后发起低烧，脸颊烧得通红，还是不肯歇着。', '小满盯着自己的影子看了很久，好像那影子不是自己的。'],
  },
  姜芸: {
    狼: ['姜芸整理着药箱，把纱布按长短重新卷好。', '姜芸主动替每个人量了体温，记录很全。'],
    民: ['姜芸检查了每个人的瞳孔和伤口，问诊很细。', '姜芸把死者的死亡时间反复推算，草稿纸写了半页。'],
    异样: ['姜芸给自己号了脉，眉头越皱越紧，草稿纸上写满了字又划掉。', '姜芸的手在轻微发抖，她把抖的手揣进了口袋。'],
  },
  苏黎: {
    狼: ['苏黎对着镜头补了三次妆，机位摆了很久。', '苏黎请大家轮流对镜头说一句话，说要留证据。'],
    民: ['苏黎翻看拍摄素材，突然停在某一段很久。', '苏黎举着手机到处找信号，指甲劈了也没察觉。'],
    异样: ['苏黎的镜头里全是糊的，她对不了焦，脾气也上来了。', '苏黎补妆时发现眼底泛青，粉盖了三层。'],
  },
  陆霜霜: {
    狼: ['陆霜霜反复查看手臂内侧，又若无其事放下袖子。', '陆霜霜把相机电池分装进每个口袋，鼓鼓囊囊。'],
    民: ['陆霜霜寸步不离苏黎，谁靠近谁挨瞪。', '陆霜霜翻来覆去看昨天拍的照片，眉头越锁越紧。'],
    异样: ['陆霜霜午睡说梦话，声音哑得不像她。', '陆霜霜的食量翻了一倍，吃完还盯着别人的盘子。'],
  },
  闻人夏: {
    狼: ['闻人夏在窗台摆了几株草，挨个闻过。', '闻人夏向众人讲解狼毒草的毒性，讲得格外详细。'],
    民: ['闻人夏背着标本袋绕庄一圈，采集雪下植物。', '闻人夏把狼毒草的标本分装成小包，说有毒能防身。'],
    异样: ['闻人夏采集时徒手掰开了一块冻土，指节咔咔作响。', '闻人夏背对着炉火坐了一夜，说热，不冷。'],
  },
  程郁: {
    狼: ['程郁把每个人的座位和发言都记在纸上。', '程郁试了试枪，又把子弹退了出来，一颗颗数。'],
    民: ['程郁勘查了每一处门窗，做了标记。', '程郁提议按房间排守夜班，自己排在最深夜里。'],
    异样: ['程郁擦枪的手停在半空，维持那个姿势足足一分钟。', '程郁把一份卷宗读错了三遍，同一行。'],
  },
  顾青芜: {
    狼: ['顾青芜替妹妹梳头，梳子在她手里停了很久。', '顾青芜给每个人分了红绳，说是家里传统。'],
    民: ['顾青芜整夜守着妹妹，眼下的青黑更重了。', '顾青芜一遍遍问姜芸：兽化前兆都有什么症状。'],
    异样: ['顾青芜一夜没合眼，第二天却说不困，声音发飘。', '顾青芜给妹妹扎头发时，手劲大得扯疼了对方。'],
  },
  顾青黛: {
    狼: ['顾青黛午睡到黄昏，醒来时眼神空了很久。', '顾青黛小声跟姐姐说了句什么，姐姐的脸色变了。'],
    民: ['顾青黛袖口一直拉得很低，遮着手腕。', '顾青黛说昨夜又梦游了，醒来在走廊上，自己也不知道。'],
    异样: ['顾青黛的瞳孔在烛光里缩成了一条细线，又慢慢散开。', '顾青黛啃指甲啃到了肉，她自己没觉得疼。'],
  },
};

// ── 藏处池（血梦指定，私密随机）──
const 藏处池 = ['衣柜底层的夹板下', '床板背面的暗格里', '枕头芯内', '行李箱的夹层', '窗框与墙的缝隙里', '暖炉后的砖缝'];

// ═══ 工具 ═══
const 读 = () => Mvu.getMvuData({ type: 'message', message_id: 'latest' });
const 写 = async (fn) => {
  const d = 读();
  await fn(d.stat_data);
  await Mvu.replaceMvuData(d, { type: 'message', message_id: 'latest' });
};
const 掷 = (p) => Math.random() < p;
const 区间 = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const 抽一 = (arr) => arr[Math.floor(Math.random() * arr.length)];
const shuffle = (arr) => _.shuffle(arr);
const 存活NPC = (s) => s._世界.存活名单.split('|').filter(Boolean);
const 狼数 = (s) => 名单11.filter((n) => s.$人物[n].身份 === '狼' && s.$人物[n].存活 === '存活').length
  + ((s._玩家.身份 === '狼' && s._玩家.存活 === '存活') ? 1 : 0);
const 好数 = (s) => {
  const 存活 = 存活NPC(s);
  const 狼N = 名单11.filter((n) => 存活.includes(n) && s.$人物[n].身份 === '狼').length;
  return 存活.length - 狼N + ((s._玩家.存活 === '存活' && s._玩家.身份 !== '狼') ? 1 : 0);
};
const 在场全部 = (s) => [...存活NPC(s), ...(s._玩家.存活 === '存活' ? ['旅人'] : [])];
const 脚本变量 = () => getVariables({ type: 'script' });
const 写脚本变量 = async (fn) => {
  const v = await getVariables({ type: 'script' });
  fn(v);
  await replaceVariables(v, { type: 'script' });
};

// 玩家行动校验（UI 是唯一入口，但裁判自校验防 UI bug / 越权）
async function 校验行动(s, 行动) {
  const 行 = { ...行动 };
  const 目标合法 = (t) => t === '旅人' || 存活NPC(s).includes(t);
  if (行.涂门 && !(s.$物品.草汁在身 === '旅人' && s.$物品.草汁存量 > 0 && 目标合法(行.涂门))) 行.涂门 = '';
  if (行.麻沸散 && !(s.$物品.药囊在身 === '旅人' && s.$物品.麻沸散已用 === '否' && 目标合法(行.麻沸散))) 行.麻沸散 = '';
  if (行.银匕随身 && s.$物品.银匕在身 !== '旅人') 行.银匕随身 = false;
  if (行.狼票 && !(s._玩家.身份 === '狼' && 目标合法(行.狼票) && 行.狼票 !== '旅人')) 行.狼票 = '';
  if (行.镜验 && !(s.$物品.铜镜在身 === '旅人' && 目标合法(行.镜验) && 行.镜验 !== '旅人')) 行.镜验 = '';
  if (行.同屋) {
    const 同意 = 行.同屋 !== '旅人' && 目标合法(行.同屋) && 行.同屋 !== '旅人'
      && (s.人物[行.同屋]?.好感 || 0) >= 参.同屋好感门槛;
    if (!同意) { 行.同屋拒绝 = 行.同屋; 行.同屋 = ''; }
  }
  return 行;
}

// ═══ 死亡处理（统一：名单/物灭/玩家标记）═══
function 死亡处理(s, 名, 死因) {
  const d = typeof 死因 === 'string' ? 死因 : '死亡';
  if (名 === '旅人') {
    s._玩家.存活 = '死亡';
    return;
  }
  s.$人物[名].存活 = d;
  s._世界.存活名单 = 存活NPC(s).filter((n) => n !== 名).join('|');
  for (const 物 of 四神职) {
    if (s.$物品[物 + '在身'] === 名) s.$物品[物 + '在身'] = ''; // 人死物灭
  }
}

// ═══ 1. 指派（先分组后落人，三组互斥）═══
// 触发：MESSAGE_SENT（玩家第一条消息）。竞态兜底：EJS 门控块对未指派态输出空态占位。
async function 指派() {
  await 写(async (s) => {
    const 池 = shuffle([...名单11, '旅人']);
    const 狼 = 池.slice(0, 4);
    const 余 = 池.slice(4);
    const 神源 = shuffle(余.slice(0, 4));
    const 神职 = {};
    四神职.forEach((职, i) => { 神职[神源[i]] = 职; });

    // 写真相（$ 层，AI 不可见）
    for (const n of 名单11) {
      s.$人物[n].身份 = 狼.includes(n) ? '狼' : (神职[n] || '民');
      s.$人物[n].持物 = 神职[n] || '';
    }
    s._玩家.身份 = 狼.includes('旅人') ? '狼' : (神职['旅人'] || '民');
    // 注意：不写 $物品.X在身 —— 物在藏处未取，取物后才有「在身」

    // 狼队互认：NPC 狼不落文本（脚本按 $身份 现算狼队名单）；玩家狼的同伴进脚本变量
    if (狼.includes('旅人')) {
      await 写脚本变量((v) => { v.同伴 = 狼.filter((x) => x !== '旅人').join('、'); });
    }

    // 玩家血梦/藏处 → 脚本变量（AI 永不可见，UI 身份卡渲染）
    const v0 = await 脚本变量();
    v0.血梦 = ''; v0.玩家藏处 = ''; v0.玩家被种夜 = 0; v0.镜验 = {}; v0.暴露 = {}; v0.互疑 = {};
    v0.同屋 = {}; v0.银匕随身 = '';
    if (s._玩家.身份 === '狼') {
      v0.血梦 = '血月之夜的梦里，你看见了同伴的脸：' + v0.同伴 + '。还有一种从骨髓里泛上来的饿，你不明白那是什么。';
    } else if (四神职.includes(s._玩家.身份)) {
      const 藏处 = 抽一(藏处池);
      v0.玩家藏处 = 藏处;
      v0.血梦 = '梦里有一只手把' + 物名[s._玩家.身份] + '塞进你掌心，一个声音说：它藏在' + 藏处 + '。守住它，守住你的命。';
    } else {
      v0.血梦 = '你梦见漫山遍野的红，雪是热的。有人在很远的地方哭，你听不清是谁。醒来时枕头是湿的，你不记得自己为什么哭。';
    }
    await replaceVariables(v0, { type: 'script' });

    // NPC 神职藏处（脚本变量）
    await 写脚本变量((v) => {
      v.藏处 = {};
      for (const [人, 职] of Object.entries(神职)) if (人 !== '旅人') v.藏处[职] = 抽一(藏处池);
    });

    s._世界.阶段 = '夜';
    s._世界.公开事实 = '第 1 夜开始了。血月升起，暴风雪封山。';
    s._世界.今日广播 = '[入夜] 血月升起。各回离屋，落闩入睡。夜里发生的事，明早谁也不会记得。';
  });
}

// ═══ 2. 取物（玩家 UI / NPC 每晨自动）═══
async function 取物() {
  await 写(async (s) => {
    const 职 = s._玩家.身份;
    if (!四神职.includes(职) || s.$物品[职 + '在身'] === '旅人') return;
    s.$物品[职 + '在身'] = '旅人';
    s._世界.今日广播 += '\n[你] 你趁四下无人，从藏处取回了那件东西。它贴着你的皮肤，凉的。';
  });
}

// ═══ 3. 毒杀（不限夜晚，即时结算；时间差只影响措辞）═══
// 核心结算——必须在写事务内调用（玩家 UI 入口走 下毒()，NPC 在夜结算事务内直接调本函数）
async function 毒杀结算(s, 下毒者, 目标) {
  s.$物品.毒药已用 = '是';
  const 当昼 = 掷(0.6);
  死亡处理(s, 目标, '毒杀');
  let 记;
  if (目标 === '旅人') {
    记 = 当昼
      ? '[毒发] 午后，你的腹中突然翻江倒海。绞痛、发冷、视野发黑——你栽倒的地方离桌边的茶盏很近。'
      : '[毒发] 入夜前，你腹中的绞痛一阵猛过一阵。你死在了自己的房间里，没人听见。';
  } else {
    记 = 当昼
      ? '[毒发] 午后，' + 目标 + ' 突然腹中绞痛，面色青黑地倒下——没等到日落。死状是中毒征候。'
      : '[毒发] 入夜前，' + 目标 + ' 被发现僵在房里，嘴角有黑血。死状是中毒征候。';
  }
  s._世界.今日广播 += '\n' + 记;
  s._世界.公开事实 += '\n' + 目标 + ' 死于毒杀。';
  // 下毒行为线索（中立可见）：给 AI 与玩家留取证线头
  if (下毒者 !== '旅人') {
    s._世界.今日广播 += '\n[晨况] ' + 下毒者 + ' 今日曾单独出入过 ' + 目标 + ' 的房间，出来时手里空了。';
  }
}

// 下毒入口（玩家 UI 独立事务）
async function 下毒(下毒者, 目标) {
  const s0 = 读().stat_data;
  if (s0.$物品.毒药已用 === '是' || s0.$物品.药囊在身 !== 下毒者) return;
  const 存在 = 目标 === '旅人' ? s0._玩家.存活 === '存活' : 存活NPC(s0).includes(目标);
  if (!存在 || 目标 === 下毒者) return;

  await 写(async (s) => {
    await 毒杀结算(s, 下毒者, 目标);
    if (目标 === '旅人') await 胜负结算(s);
  });
}

// ═══ 4. 夜结算（UI 提交入睡行动后触发）═══
async function 夜结算(玩家行动) {
  const s0 = 读().stat_data;
  if (s0._世界.阶段 !== '夜' || s0._玩家.身份 === '未指派' || s0._玩家.存活 === '死亡') return;
  const 天 = s0._世界.天数;
  const 行 = await 校验行动(s0, 玩家行动 || {});
  let 死讯 = [];
  let 线索 = [];

  await 写(async (s) => {
    const v = await 脚本变量();

    // ── 玩家被种次夜 → 兽化终局（人格沉没，§六特殊终局）──
    if (v.玩家被种夜 && 天 > v.玩家被种夜) {
      s._世界.公开事实 += '\n【终局】' + JSON.stringify({ 类型: '兽化' });
      await eventEmit('血月-终局', { 类型: '兽化' });
      return;
    }

    // ── 同屋申报（好感门槛；结果进广播供 AI 渲染）──
    if (行.同屋拒绝) {
      s._世界.今日广播 += '\n[入夜] 你敲开了 ' + 行.同屋拒绝 + ' 的门。对方只开了一条缝，摇摇头，把门关上了。';
    } else if (行.同屋) {
      v.同屋 = { [行.同屋]: '旅人', '旅人': 行.同屋 };
      s._世界.今日广播 += '\n[入夜] 今夜 ' + 行.同屋 + ' 与你同屋。两道门闩，落了双份。';
    }

    const 存活 = 存活NPC(s);
    const 狼队 = 名单11.filter((n) => 存活.includes(n) && s.$人物[n].身份 === '狼');
    const 玩家是狼 = s._玩家.身份 === '狼' && s._玩家.存活 === '存活';
    if (玩家是狼) 狼队.push('旅人');

    // ── 被种者发作（§九夜袭名额：兽袭与围猎共享「每夜夜袭死 ≤1」）──
    // 多兽并存时合计掷一次（概率随兽数微增封顶 0.9），防一夜雪崩
    const 活跃兽 = 名单11.filter((n) => 存活.includes(n) && s.$人物[n].被种 && s.$人物[n].兽化 !== '完成');
    for (const 兽 of 活跃兽) {
      if (s.$人物[兽].兽化 === '无') s.$人物[兽].兽化 = '进行中';
    }
    let 兽袭得手 = false;
    if (活跃兽.length) {
      const 兽袭概率 = Math.min(0.9, 参.兽袭 + 0.1 * (活跃兽.length - 1));
      if (掷(兽袭概率)) {
        const 兽 = 抽一(活跃兽);
        const 猎池 = [...存活NPC(s).filter((n) => n !== 兽)];
        if (s._玩家.存活 === '存活') 猎池.push('旅人');
        if (猎池.length) {
          const 猎物 = 抽一(猎池);
          兽袭得手 = true;
          死亡处理(s, 猎物, '夜行兽袭击');
          死讯.push(猎物 === '旅人' ? '你在半梦半醒中听见了抓挠声——然后是剧痛。' : 猎物 + ' 死了，门口有大型兽类的爪痕，血迹拖出去很远。');
          if (猎物 === '旅人') { await 胜负结算(s); return; }
        }
      } else {
        线索.push('雪地上有不明的兽爪印，绕着离屋转了一圈，消失在后山方向。');
      }
    }
    if (s._玩家.存活 === '死亡') return;

    // ── NPC 取物（每晨自动，隐秘完成；用实时存活——死者不取物）──
    for (const n of 存活NPC(s)) {
      const 职 = s.$人物[n].持物;
      if (职 && s.$物品[职 + '在身'] !== n) s.$物品[职 + '在身'] = n;
    }

    // ── NPC 持物人策略行动（实时存活）──
    const 今夜保护 = {};
    // 玩家行动（已校验）
    if (行.涂门) { 今夜保护[行.涂门] = '草汁'; s.$物品.草汁存量 -= 1; }
    if (行.麻沸散) { 今夜保护[行.麻沸散] = '麻沸散'; s.$物品.麻沸散已用 = '是'; }
    // 玩家持铜镜夜验（结果即刻入脚本变量镜验，属白天记忆——§2.5）
    if (行.镜验) {
      const 果 = s.$人物[行.镜验].身份 === '狼' ? '雾聚——是狼' : '镜面清澈——是人';
      v.镜验['旅人'] = (v.镜验['旅人'] || '') + '【镜验·第' + 天 + '夜】' + 行.镜验 + ' ' + 果 + '；';
    }
    // NPC 行动
    for (const n of 存活NPC(s)) {
      const 职 = s.$人物[n].持物;
      if (!职 || s.$人物[n].兽化 !== '无') continue;
      if (职 === '草汁' && s.$物品.草汁存量 > 0 && 掷(参.NPC草汁自守)) {
        今夜保护[n] = '草汁';
        s.$物品.草汁存量 -= 1;
      }
      if (职 === '药囊' && s.$物品.麻沸散已用 === '否' && 掷(参.NPC麻沸散自守)) {
        今夜保护[n] = '麻沸散';
        s.$物品.麻沸散已用 = '是';
        v.今夜麻沸 = n; // 晨起头痛线索用
      }
      if (职 === '铜镜') {
        const 未验 = 存活.filter((x) => x !== n && !(v.镜验[n] || '').includes(x));
        if (未验.length) {
          // §十：验「互疑度最高」的未验者
          const 目标 = [...未验].sort((a, b) => ((v.互疑[n]?.[b] || 0) - (v.互疑[n]?.[a] || 0)))[0];
          const 果 = s.$人物[目标].身份 === '狼' ? '雾聚——是狼' : '镜面清澈——是人';
          v.镜验[n] = (v.镜验[n] || '') + '【镜验】' + 目标 + ' ' + 果 + '；';
          // 私知存脚本变量，不进 _人物（AI 不可见；传递后才入账）
        }
      }
      if (职 === '银匕') v.银匕随身 = 掷(参.NPC银匕随身) ? n : '';
      // NPC 药囊持有者的下毒策略（怀疑最高者；一次性）
      if (职 === '药囊' && s.$物品.毒药已用 === '否' && 掷(参.NPC下毒)) {
        const 候 = 在场全部(s).filter((x) => x !== n);
        if (候.length) {
          const 目标 = 候.reduce((a, b) => {
            const w = (x) => x === '旅人' ? (s.人物[n]?.怀疑 || 0) + 10 : (v.互疑[n]?.[x] || 区间(10, 30));
            return w(a) >= w(b) ? a : b;
          });
          await 毒杀结算(s, n, 目标);
          if (目标 === '旅人') { await 胜负结算(s); return; }
        }
      }
    }
    if (v.今夜麻沸) {
      线索.push(v.今夜麻沸 === '旅人' ? '你晨起头痛欲裂，像有人在你颅骨里敲了一夜锤子。' : v.今夜麻沸 + ' 晨起头痛欲裂，脸色很差——那屋子昨夜被动过。');
      delete v.今夜麻沸;
    }

    // ── 狼队夜议（目标选择；兽袭得手则今夜不猎——夜袭名额已用，§九）──
    let 猎物 = null;
    if (!兽袭得手 && 狼队.length > 0) {
      // 已被种的不重复猎（种在身上，等它发作）
      const 猎池 = 存活.filter((n) => !狼队.includes(n) && !s.$人物[n].被种);
      if (!玩家是狼 && s._玩家.存活 === '存活' && !v.玩家被种夜) 猎池.push('旅人');
      if (猎池.length) {
        // 权重：基础 + 公开暴露（传递过神信息的人）+ 随机
        const 权 = {};
        for (const x of 猎池) {
          权[x] = 10 + (x === '旅人' ? 0 : (v.暴露[x] || 0)) + 区间(0, 15);
        }
        if (玩家是狼 && 行.狼票 && 权[行.狼票]) 权[行.狼票] += 100;
        猎物 = 猎池.reduce((a, b) => (权[a] >= 权[b] ? a : b));
      }
    }

    // ── 围猎结算 ──
    if (猎物) {
      const 被护 = !!今夜保护[猎物];
      if (被护) {
        线索.push('夜里狼嚎绕着庄子转了半圈，悻悻远去——有人的防线起作用了。');
      } else {
        const 目标随身银匕 = 猎物 === '旅人' ? !!行.银匕随身 : (s.$物品.银匕在身 === 猎物 && v.银匕随身 === 猎物);
        let 完成 = false;
        if (目标随身银匕) {
          const r = Math.random();
          if (r < 参.搏命同归) {
            const 真狼池 = 狼队.filter((n) => n !== '旅人');
            const 死狼 = 真狼池.length ? 抽一(真狼池) : null;
            死讯.push((猎物 === '旅人' ? '你' : 猎物) + ' 在围猎中拔出银匕，捅穿了一头狼的心口——但没能等来天亮。');
            if (死狼) 死亡处理(s, 死狼, '银器伤');
            死亡处理(s, 猎物, '银器伤');
            if (猎物 === '旅人') { await 胜负结算(s); return; }
            完成 = true;
          } else if (r < 参.搏命同归 + 参.搏命击退) {
            死讯.push('夜里屋外传来惨嚎和搏斗声，雪地上有血，但没有死者。');
            线索.push((猎物 === '旅人' ? '你的门板' : 猎物 + '的门板') + '上有抓痕和焦黑的银器灼痕。');
            完成 = true;
          }
        }
          if (!完成) {
          if (掷(参.做死)) {
            死亡处理(s, 猎物, '围猎致死');
            死讯.push(猎物 === '旅人' ? '它们按住了你。热气、腥味、撕扯——你在极度的快感与疼痛里失去了意识，再也没有醒来。' : 猎物 + ' 死了。死状有多人性事痕迹、咬颈扼痕，是多人所为。');
            if (猎物 === '旅人') { await 胜负结算(s); return; }
          } else {
            // 留种：对外无信息（死讯不点破），被种者私知在 $ 层
            if (猎物 === '旅人') {
              v.玩家被种夜 = 天; // 玩家不在 $人物，被种记脚本变量
            } else {
              s.$人物[猎物].被种 = '第' + 天 + '夜被种';
            }
            死讯.push('今夜无人死。');
          }
        }
      }
    } else if (!兽袭得手 && 狼队.length > 0) {
      线索.push('血月当空，庄子里静得可怕——今夜它们没有得手，但它们一定会再来的。');
    }

    // ── 同屋活口线索（死者若有同屋者）──
    for (const 记 of [...死讯]) {
      const 死者名 = 名单11.find((n) => 记.startsWith(n + ' 死了'));
      if (死者名 && v.同屋[死者名]) {
        const 活口 = v.同屋[死者名];
        const 活口存活 = 活口 === '旅人' ? s._玩家.存活 === '存活' : 存活.includes(活口);
        if (活口存活) 死讯.push('她死在与 ' + 活口 + ' 同住的屋里——' + (活口 === '旅人' ? '而你' : 活口) + '毫发无伤。');
      }
    }
    v.同屋 = {}; // 同屋关系只保当夜

    // ── 晨间状态更新 ──
    s._世界.阶段 = '昼';
    s._世界.昨夜死讯 = 死讯.join('\n');

    // 行为指令生成（中立措辞：狼面/好人面按 $身份 抽取；被种者追加异样）
    const 存活2 = 存活NPC(s);
    for (const n of 存活2) {
      const 面 = s.$人物[n].身份 === '狼' ? '狼' : '民';
      线索.push(抽一(行为池[n][面]));
      if (s.$人物[n].被种 && s.$人物[n].兽化 !== '完成') 线索.push(抽一(行为池[n].异样));
    }
    const 死者们 = 名单11.filter((n) => s.$人物[n].存活 !== '存活');
    if (死者们.length) 线索.push('停灵间里躺着 ' + 死者们.join('、') + '。');

    // 知情集摘要（只含公开传递——_人物.已知 现在只有【传递】入账，无私密）
    const 知情 = 存活2.filter((n) => s._人物[n].已知).map((n) => n + '知道：' + s._人物[n].已知.trim());

    s._世界.今日广播 = [
      死讯.length ? '[死讯]\n' + 死讯.join('\n') : '[死讯] 今夜无人死。',
      线索.length ? '[晨况]\n' + 线索.join('\n') : '',
      知情.length ? '[知情]\n' + 知情.join('\n') : '',
    ].filter(Boolean).join('\n\n');

    // 玩家晨起被种异样（不点破被种——§3.5 隐瞒窗口）
    if (v.玩家被种夜 === 天) {
      s._世界.今日广播 += '\n[你] 你醒来时低烧、乏力，小腹深处有什么东西在发烫。你不记得昨夜发生了什么。';
    }

    // ── 传递事件消费（AI 申报 → 裁决入账）──
    if (s.世界.传递事件) {
      for (const 行文 of s.世界.传递事件.split('\n')) {
        const p = 行文.split('→').map((x) => x.trim());
        if (p.length === 3 && 存活2.includes(p[0]) && 存活2.includes(p[1])) {
          const [传递者, 接收者, 内容] = p;
          s._人物[接收者].已知 += ' 【传递】' + 传递者 + '告诉你：' + 内容 + '。';
          if (/镜|是狼|毒|麻沸|草汁|银匕/.test(内容)) {
            v.暴露 = v.暴露 || {};
            v.暴露[传递者] = (v.暴露[传递者] || 0) + 参.神信息暴露;      // 说者暴露给狼队
            v.互疑 = v.互疑 || {};
            v.互疑[接收者] = v.互疑[接收者] || {};
            v.互疑[接收者][传递者] = (v.互疑[接收者][传递者] || 0) + 参.行为可疑; // 听者起疑
          }
        }
      }
      s.世界.传递事件 = '';
    }

    // NPC 间死亡也可能触发终局（处决狼→好人胜 / 围猎耗血→狼胜）——每晨统一判一次
    await 胜负结算(s);
    await replaceVariables(v, { type: 'script' });
  });
}

// ═══ 5. 投票处决（UI 提交投票后触发；票={目标, 以银}）═══
async function 投票处决(玩家票) {
  const s0 = 读().stat_data;
  if (s0._世界.阶段 !== '昼' || s0._玩家.存活 === '死亡') return;
  const 票 = 玩家票 || {};

  await 写(async (s) => {
    const v = await 脚本变量();
    const 存活 = 存活NPC(s);
    const 候选 = [...存活];
    if (s._玩家.存活 === '存活') 候选.push('旅人');

    // NPC 票：对玩家 = 怀疑 × (1.5 - 好感/100)（占位公式，方向：好感高→权重低）；NPC 互投 = 互疑记录 + 随机
    const 票箱 = {};
    for (const n of 存活) {
      const 权 = {};
      for (const x of 候选) {
        if (x === n) continue;
        let w = x === '旅人'
          ? Math.max(1, (s.人物[n]?.怀疑 || 0) * (1.5 - (s.人物[n]?.好感 || 0) / 100))
          : Math.max(1, (v.互疑[n]?.[x] || 0) || 区间(10, 25)); // 无记录的 NPC 互猜基线高于玩家初始怀疑（防玩家天生票王）
        权[x] = w;
      }
      const 目标 = 候选.filter((x) => x !== n).reduce((a, b) => (权[a] >= 权[b] ? a : b));
      票箱[目标] = (票箱[目标] || 0) + 1;
    }
    if (票.目标 && 候选.includes(票.目标)) 票箱[票.目标] = (票箱[票.目标] || 0) + 1;

    const 总票 = Object.values(票箱).reduce((a, b) => a + b, 0);
    const [目标, 票数] = Object.entries(票箱).sort((a, b) => b[1] - a[1])[0];
    const 过半 = 票数 > 总票 / 2;

    if (!过半 || !目标) {
      s._世界.公开事实 += '\n平票——今日无人处决（平安日）。所有人都知道，狼今夜不会客气。';
      s._世界.今日广播 = '[处决] 平票，无人被处决。平安日是坏消息：狼必开刀。';
      await 入夜翻转(s);
      return;
    }

    const 是玩家 = 目标 === '旅人';
    const 真身份 = 是玩家 ? s._玩家.身份 : s.$人物[目标].身份;
    let 处决记 = 目标 + ' 被判众刑（' + 票数 + ' 票过半）。';

    // 以银代众（§4.3）：被处决者自刎 / 行刑方持匕代众——双向，银匕消耗
    let 以银 = false;
    if (s.$物品.银匕在身 === 目标) {
      以银 = 是玩家 ? !!票.以银 : 掷(参.NPC自刎);
    } else if (是玩家) {
      以银 = !!票.以银 && s.$物品.银匕在身 === '旅人';
    } else if (存活.includes(s.$物品.银匕在身)) {
      以银 = 掷(参.NPC代众); // 银匕在身=持有人名；此处为活着的 NPC 行刑方持匕
    }
    if (以银) {
      s.$物品.银匕在身 = '';
      处决记 += ' 银匕出鞘，一人一刀，免了众刑。银匕从此消失。';
    } else {
      处决记 += ' 全体生者行刑，狼之法，交合耗杀。';
    }

    // 死亡与验真伪
    死亡处理(s, 目标, '处决');
    const 现原形 = 真身份 === '狼';
    处决记 += 现原形 ? ' 死状现出原形——她是狼。' : ' 死后并无原形——她是无辜的。冤案。';
    s._世界.公开事实 += '\n' + 处决记;

    // 头狼之性（被处决者是狼 → 反扑）
    if (现原形 && 掷(参.反扑)) {
      const 行刑池 = 存活NPC(s);
      if (行刑池.length) {
        const 带走 = 抽一(行刑池);
        死亡处理(s, 带走, '反扑');
        s._世界.公开事实 += '\n垂死的狼暴起反扑，带走了 ' + 带走 + '。行刑的顺序，从此成了参与恐惧的排序。';
      }
    }

    s._世界.昨夜死讯 = '';
    s._世界.今日广播 = '[处决]\n' + 处决记;
    if (是玩家) { await 胜负结算(s); return; }
    // 处决狼→好人胜 / 反扑后狼数达标→狼胜——翻转前先判
    const 已终局 = await 胜负结算(s);
    if (已终局) { await replaceVariables(v, { type: 'script' }); return; }
    await 入夜翻转(s);
    await replaceVariables(v, { type: 'script' });
  });
}

// 入夜翻转（处决/平票后）：已是第七昼还翻转 = 七夜耗尽
async function 入夜翻转(s) {
  if (s._世界.天数 >= 7) {
    s._世界.阶段 = '夜'; // 虚拟的「第八夜」只为匹配耗尽判定
    await 胜负结算(s);
    return;
  }
  s._世界.天数 += 1;
  s._世界.阶段 = '夜';
  s._世界.今日广播 += '\n[入夜] 第 ' + s._世界.天数 + ' 夜。血月再次升起。';
}

// ═══ 6. 胜负（优先级：玩家死亡 > 狼数≥好数 > 狼全灭 > 七夜耗尽）═══
// 返回终局对象（无终局返回 null）
async function 胜负结算(s) {
  let 终局 = null;
  if (s._玩家.存活 === '死亡') {
    终局 = { 类型: '死档', 身份: s._玩家.身份, 死因: s._世界.昨夜死讯 || '处决' };
  } else if (狼数(s) >= 好数(s)) {
    终局 = { 类型: s._玩家.身份 === '狼' ? '狼胜' : '灭亡' };
  } else if (狼数(s) === 0) {
    终局 = { 类型: '好人胜' };
  } else if (s._世界.天数 >= 7 && s._世界.阶段 === '夜') {
    终局 = { 类型: '七夜耗尽' };
  }
  if (终局) {
    s._世界.公开事实 += '\n【终局】' + JSON.stringify(终局);
    await eventEmit('血月-终局', 终局);
  }
  return 终局;
}

// ═══ 重开（重置到 initvar 态；更干净的做法是新开聊天）═══
async function 重开() {
  await 写(async (s) => {
    s._世界.天数 = 1; s._世界.阶段 = '昼';
    s._世界.存活名单 = 名单11.join('|');
    s._世界.昨夜死讯 = ''; s._世界.公开事实 = ''; s._世界.今日广播 = '';
    s._玩家.身份 = '未指派'; s._玩家.存活 = '存活';
    s.世界.传递事件 = '';
    for (const n of 名单11) {
      s.$人物[n] = { 身份: '未指派', 持物: '', 被种: '', 兽化: '无', 存活: '存活' };
      s._人物[n] = { 已知: '' };
    }
    s.$物品 = { 草汁存量: 3, 毒药已用: '否', 麻沸散已用: '否', 银匕在身: '', 铜镜在身: '', 草汁在身: '', 药囊在身: '' };
  });
  await 写脚本变量((v) => {
    v.血梦 = ''; v.同伴 = ''; v.玩家藏处 = ''; v.玩家被种夜 = 0;
    v.藏处 = {}; v.互疑 = {}; v.照过 = []; v.镜验 = {}; v.暴露 = {};
    v.同屋 = {}; v.银匕随身 = ''; v.今夜麻沸 = '';
  });
  await eventEmit('血月-已重开');
}

// ═══ 事件接线 ═══
// 指派：玩家第一条消息发出时。注：回调 async 不阻塞生成流程，竞态兜底由
// EJS 门控块承担（未指派态输出空态占位，AI 见空态不乱写）。
eventOn(tavern_events.MESSAGE_SENT, async () => {
  const s = 读().stat_data;
  if (s._玩家 && s._玩家.身份 === '未指派') await 指派();
});

// UI 通道
eventOn('血月-入睡', async (行动) => { await 夜结算(行动 || {}); });
eventOn('血月-投票', async (票) => { await 投票处决(票 || {}); });
eventOn('血月-取物', async () => { await 取物(); });
eventOn('血月-下毒', async (p) => { await 下毒('旅人', (p && p.目标) || ''); });
eventOn('血月-重开', async () => { await 重开(); });

// AI 每轮变量更新结束后：好感/怀疑单次增幅限幅（第二道防线，第一道是 schema clamp）
eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (variables, before) => {
  for (const n of 名单11) {
    for (const 键 of ['好感', '怀疑']) {
      const 路径 = 'stat_data.人物.' + n + '.' + 键;
      const 旧 = _.get(before, 路径);
      const 新 = _.get(variables, 路径);
      if (typeof 旧 === 'number' && typeof 新 === 'number') {
        _.set(variables, 路径, _.clamp(新, 旧 - 12, 旧 + 12));
      }
    }
  }
});

// 共享接口（UI 调用）
initializeGlobal('血月裁判', { 指派, 夜结算, 投票处决, 取物, 下毒, 重开, 参 });

import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';
// 血月七夜 · MVU 变量结构定义（Zod 4）
// 禁止 import —— z（Zod v4）与 _（lodash）已全局注入
// 前缀约定：_ = AI 可见不可改（脚本产出）；$ = AI 不可见（脚本专属真相）；无前缀 = AI 可见可改（仅好感/怀疑/传递事件）
// 铁律：名单/事实/指令全部字符串整串 replace，不用数组；11 人命名空间用 z.record(z.enum) 固定键，预置于 initvar

export const Schema = z.object({
  _世界: z
    .object({
      天数: z.coerce
        .number()
        .transform((v) => _.clamp(v, 1, 7))
        .prefault(1),
      阶段: z.enum(['夜', '昼']).prefault('昼'),
      存活名单: z
        .string()
        .prefault('庄晚棠|白蘅|灶婶|小满|姜芸|苏黎|陆霜霜|闻人夏|程郁|顾青芜|顾青黛'),
      昨夜死讯: z.string().prefault(''),
      公开事实: z.string().prefault(''),
      今日广播: z.string().prefault(''),
    })
    .prefault({}),
  // 玩家血梦/同伴/藏处/被种夜一律存脚本变量（AI 不可见，UI 读）——_ 前缀字段会注入 prompt
  _玩家: z
    .object({
      身份: z.enum(['未指派', '狼', '民', '铜镜', '药囊', '银匕', '草汁']).prefault('未指派'),
      存活: z.enum(['存活', '死亡']).prefault('存活'),
    })
    .prefault({}),
  _人物: z
    .record(
      z.enum(['庄晚棠', '白蘅', '灶婶', '小满', '姜芸', '苏黎', '陆霜霜', '闻人夏', '程郁', '顾青芜', '顾青黛']),
      z.object({
        已知: z.string().prefault(''),
      }),
    )
    .prefault({}),
  人物: z
    .record(
      z.enum(['庄晚棠', '白蘅', '灶婶', '小满', '姜芸', '苏黎', '陆霜霜', '闻人夏', '程郁', '顾青芜', '顾青黛']),
      z.object({
        好感: z.coerce
          .number()
          .transform((v) => _.clamp(v, 0, 100))
          .prefault(50),
        怀疑: z.coerce
          .number()
          .transform((v) => _.clamp(v, 0, 100))
          .prefault(15),
      }),
    )
    .prefault({}),
  世界: z
    .object({
      传递事件: z.string().prefault(''),
    })
    .prefault({}),
  $物品: z
    .object({
      草汁存量: z.coerce
        .number()
        .transform((v) => _.clamp(v, 0, 3))
        .prefault(3),
      毒药已用: z.enum(['否', '是']).prefault('否'),
      麻沸散已用: z.enum(['否', '是']).prefault('否'),
      银匕在身: z.string().prefault(''),
      铜镜在身: z.string().prefault(''),
      草汁在身: z.string().prefault(''),
      药囊在身: z.string().prefault(''),
    })
    .prefault({}),
  $人物: z
    .record(
      z.enum(['庄晚棠', '白蘅', '灶婶', '小满', '姜芸', '苏黎', '陆霜霜', '闻人夏', '程郁', '顾青芜', '顾青黛']),
      z.object({
        身份: z.enum(['未指派', '狼', '民', '铜镜', '药囊', '银匕', '草汁']).prefault('未指派'),
        持物: z.string().prefault(''),
        被种: z.string().prefault(''),
        兽化: z.enum(['无', '进行中', '完成']).prefault('无'),
        存活: z.string().prefault('存活'),
      }),
    )
    .prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
});

